1	/**
2	 * new-release-notice.test.ts — the workflow that says a newer release exists
3	 * stays the one thing it was built to be: a notice.
4	 *
5	 * ## Why this is pinned
6	 *
7	 * It is a generated workflow that runs unattended, on a cron, in every adopter's
8	 * repository, and it writes to their issue tracker. Three things about it are one
9	 * edit away from being lost and none of them fail loudly:
10	 *
11	 * - **the permission set.** Broadening it costs nothing visible. `contents: read` +
12	 *   `issues: write` + `actions: write` is also the whole argument for shipping this
13	 *   half of the upgrade problem before the sync half, so losing it silently withdraws
14	 *   the reason: `actions` is what starts the update workflow the notice announces,
15	 *   and `checks: write` is what it must never hold, because that is the permission
16	 *   that could produce a check result of its own.
17	 * - **no dispatch of its own, and no checkout of anything else.** The notice is a
18	 *   read of two release tags, one issue write, and -- only for a repository that
19	 *   asked -- one dispatch through `dispatchUpdate`. Anything that runs `gh workflow
20	 *   run` in its shell, writes a workflow or opens a pull request from here would be
21	 *   the capability this was designed NOT to need, in the place nobody can gate it.
22	 * - **the schedule, and its absence in the other direction.** A cron is easy to
23	 *   delete while tidying and impossible to notice afterwards: the workflow stays
24	 *   green and simply never runs.
25	 *
26	 * `notify_new_release.test.ts` beside the script holds the behaviour; this holds
27	 * the wiring, which the script cannot see.
28	 */
29	import { describe, expect, test } from "bun:test";
30	import { readFileSync } from "node:fs";
31	import { UPSTREAM_REPOSITORY } from "../../src/entrypoints/machinery/notify_new_release.ts";
32	
33	type Step = { name?: string; uses?: string; run?: string; env?: Record<string, string>; with?: Record<string, string> };
34	type Document = {
35	  on?: { schedule?: { cron?: string }[]; workflow_dispatch?: unknown; [trigger: string]: unknown };
36	  permissions?: Record<string, string>;
37	  jobs?: Record<string, { "timeout-minutes"?: number; steps?: Step[] }>;
38	};
39	
40	const WORKFLOW = "dist/.github/workflows/atomaton-new-release.yml";
41	const document = Bun.YAML.parse(readFileSync(WORKFLOW, "utf8")) as Document;
42	const jobs = Object.entries(document.jobs ?? {});
43	
44	/** Every step of every job. */
45	const steps = jobs.flatMap(([, job]) => job.steps ?? []);
46	
47	describe("the new-release notice", () => {
48	  test("it runs on a schedule, and a person can press it", () => {
49	    // Both halves: a cron is what reaches a repository nobody is looking at, and
50	    // the dispatch is what lets somebody who IS looking ask now.
51	    expect(document.on?.schedule?.[0]?.cron, "without a cron this never fires on its own").toBeTruthy();
52	    expect(document.on).toHaveProperty("workflow_dispatch");
53	  });
54	
55	  /**
56	   * Nothing else triggers it. An `issues` or `push` trigger here would re-post the
57	   * notice on every comment and every merge -- and in an adopted repository that is
58	   * every event its own agents generate.
59	   */
60	  test("nothing else triggers it", () => {
61	    expect(Object.keys(document.on ?? {}).sort()).toEqual(["schedule", "workflow_dispatch"]);
62	  });
63	
64	  /**
65	   * The permission set, exactly. Read on releases, write on issues, and `actions:
66	   * write` to start the update workflow — that is the whole of what the notice needs,
67	   * and the third is the one this test used to forbid.
68	   *
69	   * It forbade it because the dispatch used to run as the update's PAT instead, and
70	   * the argument then was that widening the permission of the job that rewrites
71	   * `.github/` is a bigger decision than carrying a token that already exists. The
72	   * token turned out not to have `Actions` in its documented scope — `Contents`,
73	   * `Pull requests`, `Workflows` — so a repository set up as documented got a 403 on
74	   * every dispatch, and the notice it fell back to said the update had not been
75	   * started. `workflow_dispatch` is the documented exception a `GITHUB_TOKEN` can
76	   * still make, which is why every other machinery dispatch already works this way.
77	   */
78	  test("it holds `contents: read`, `issues: write` and `actions: write` and nothing else", () => {
79	    expect(document.permissions).toEqual({ contents: "read", issues: "write", actions: "write" });
80	  });
81	
82	  test("one job, bounded", () => {
83	    expect(jobs).toHaveLength(1);
84	    for (const [name, job] of jobs) {
85	      expect(job["timeout-minutes"], `${name} is bounded only by GitHub's default`).toBeGreaterThan(0);
86	    }
87	  });
88	
89	  /**
90	   * It reads the adopted tree's own checkout and nothing else, and it writes no
91	   * workflow: `.github/workflows/**` is refused to `GITHUB_TOKEN` on identity, so a
92	   * step here that tried would fail in the adopter's repository rather than in
93	   * this one.
94	   */
95	  test("it writes nothing but an issue", () => {
96	    const writes = steps
97	      .map((step) => step.run ?? "")
98	      .flatMap((body) => [...body.matchAll(/bun run "[^"]*\/([a-z_]+\.ts)"/g)].map((m) => m[1] ?? ""));
99	    expect(writes, "the step that writes the notice").toContain("notify_new_release.ts");
100	    expect(writes, "one script, so the whole behaviour is in one place").toEqual(["notify_new_release.ts"]);
101	  });
102	
103	  /**
104	   * The step's own bash does nothing else either. A `gh pr create` or a
105	   * `gh workflow run` beside the notice would be the automatic-update capability
106	   * this workflow was deliberately not given.
107	   */
108	  test("its shell opens no pull request and starts no run", () => {
109	    const bodies = steps.map((step) => step.run ?? "").join("\n");
110	    expect(bodies).not.toMatch(/gh\s+pr\s+create/);
111	    expect(bodies).not.toMatch(/gh\s+workflow\s+run/);
112	  });
113	
114	  /** The repository travels as an env value, so the one source of it is the context. */
115	  test("the repository it writes to comes from the workflow context", () => {
116	    const step = steps.find((candidate) => (candidate.run ?? "").includes("notify_new_release.ts"));
117	    expect(step).toBeDefined();
118	    expect(step?.env?.GH_TOKEN, "the notice needs a token with `issues: write`").toBe("${{ github.token }}");
119	    expect(step?.env?.REPO).toBe("${{ github.repository }}");
120	    expect(step?.run).toContain('--repo "${REPO}"');
121	  });
122	
123	  /**
124	   * And one secret, read for the mode that asked for it and required by neither.
125	   *
126	   * The ordering this half exists to protect is unchanged: a repository that
127	   * configures nothing is told there is an upgrade with no secret at all. What the
128	   * PAT buys is no longer the dispatch -- the workflow's own `actions: write` starts
129	   * the run, so a PAT without `Actions` in its scope is enough -- but the update the
130	   * dispatch starts, which pushes, opens its pull request and merges only as that
131	   * identity, and the pull-request read this notice makes along `openPrForHead`,
132	   * which its permission block does not grant. So the secret travels inside the
133	   * step's env, where the script reads it and can say "nothing was started" instead
134	   * of failing.
135	   *
136	   * Named exactly, because a second secret here would be a second thing an adopter
137	   * has to mint before being told about a release.
138	   */
139	  test("the one secret it reads is the update's own token, and only the notice step sees it", () => {
140	    const text = readFileSync(WORKFLOW, "utf8");
141	    const named = [...text.matchAll(/secrets\.([A-Za-z0-9_]+)/g)].map((match) => match[1] ?? "");
142	    expect([...new Set(named)]).toEqual(["ATOMATON_UPDATE_TOKEN"]);
